import heapq

def dijkstra(adj, src):                # adj[u] = [(v, w), ...], all w >= 0
    dist = {src: 0}
    heap = [(0, src)]
    while heap:
        d, u = heapq.heappop(heap)
        if d > dist[u]:
            continue                   # stale entry: heapq has no decrease-key
        for v, w in adj.get(u, []):
            nd = d + w
            if nd < dist.get(v, float("inf")):
                dist[v] = nd           # relax
                heapq.heappush(heap, (nd, v))
    return dist

def bellman_ford(n, edges, src):       # edges = [(u, v, w)], w may be < 0
    dist = [float("inf")] * n
    dist[src] = 0
    for _ in range(n - 1):             # a shortest path has at most n-1 edges
        for u, v, w in edges:
            if dist[u] + w < dist[v]:
                dist[v] = dist[u] + w
    for u, v, w in edges:              # still improving? negative cycle
        if dist[u] + w < dist[v]:
            raise ValueError("negative cycle reachable from src")
    return dist

